class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now }) {
    if (typeof capacity !== 'number' || !isFinite(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.now = now;

    // Başlangıçta kova dolu
    this.tokens = capacity;
    this.lastRefillTime = now();
  }

  tryTake(n = 1) {
    if (typeof n !== 'number' || !isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }

    const nowTime = this.now();
    this._refill(nowTime);

    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    const nowTime = this.now();
    this._refill(nowTime);
    return this.tokens;
  }

  msUntil(n = 1) {
    if (typeof n !== 'number' || !isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }

    // refillPerSecond sıfırsa ve n > capacity ise sonsuzluk döndür
    if (this.refillPerSecond === 0 && n > this.capacity) {
      return Infinity;
    }

    const nowTime = this.now();
    this._refill(nowTime);

    // Eğer istenen jeton sayısı kapasiteden fazlaysa sonsuzluk döndür
    if (n > this.capacity) {
      return Infinity;
    }

    // Kova doluysa 0 dön
    if (this.tokens >= n) {
      return 0;
    }

    // Ne kadar zaman gerekli?
    const neededTokens = n - this.tokens;
    const refillRatePerMs = this.refillPerSecond / 1000;
    const requiredTimeMs = neededTokens / refillRatePerMs;

    return Math.ceil(requiredTimeMs);
  }

  _refill(nowTime) {
    // Saat geri gidiyor veya aynı zamanda olursa doldurma yapma
    if (nowTime <= this.lastRefillTime) {
      return;
    }

    const timePassed = nowTime - this.lastRefillTime;
    const refillAmount = (timePassed / 1000) * this.refillPerSecond;

    // Yeni jeton miktarı, kapasiteye göre sınırlanır
    this.tokens = Math.min(this.capacity, this.tokens + refillAmount);
    this.lastRefillTime = nowTime;
  }
}

module.exports = { TokenBucket };

const { TokenBucket } = require('./kova.js');

// Basit testler
console.log('Test 1: TokenBucket oluşturuluyor');
const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
console.log('Kapaite ve dolum hızı doğru ayarlandı.');

console.log('\nTest 2: tryTake ile jeton alınması');
console.log(bucket.tryTake(3)); // true
console.log(bucket.tryTake(8)); // false (yeterli jeton yok)
console.log(bucket.available()); // 7

console.log('\nTest 3: msUntil testi');
console.log(bucket.msUntil(1)); // 0 (jeterli jeton var)

console.log('\nTest 4: Geçersiz kapasite');
try {
  new TokenBucket({ capacity: -1, refillPerSecond: 2 });
} catch (e) {
  console.log('Geçersiz kapasite hatası:', e.message);
}

console.log('\nTest 5: Geçersiz dolum hızı');
try {
  new TokenBucket({ capacity: 10, refillPerSecond: -1 });
} catch (e) {
  console.log('Geçersiz dolum hızı hatası:', e.message);
}

// Sahte saat testi
console.log('\nTest 6: Sahte saat testi');
let fakeTime = 0;
const fakeBucket = new TokenBucket({
  capacity: 10,
  refillPerSecond: 2,
  now: () => fakeTime
});

fakeTime = 5000; // 5 saniye sonra
console.log('Fake zaman:', fakeTime);
console.log('Jeton sayısı:', fakeBucket.available());

console.log('\nTestler tamamlandı.');

